{"decision":{"analyze":"def act(history):
    import math
    states = history['states']
    actions = history['actions']
    n = len(actions)
    menu = [[0.6,0.0],[0.519615242271,0.3],[0.3,0.519615242271],[0.0,0.6],[-0.3,0.519615242271],[-0.519615242271,0.3],[-0.6,0.0],[-0.519615242271,-0.3],[-0.3,-0.519615242271],[0.0,-0.6],[0.3,-0.519615242271],[0.519615242271,-0.3],[0.0,0.0]]
    def phase(axis, t, x, y):
        if axis == 't':
            return float(t)
        if axis == 'x':
            return x
        if axis == 'r2':
            return x*x+y*y
        if axis == 't2':
            return float(t*t)
        return y
    def features(spec, t, x, y, u, v):
        kind, axis, w, bias = spec
        if kind == 'linear':
            f = [x,y,u,v]
        elif kind == 'gain':
            g = 1.0/(1.0+w*(u*u+v*v))
            f = [x,y,g*u,g*v]
        else:
            angle = w*phase(axis,t,x,y)
            c,s = math.cos(angle),math.sin(angle)
            if kind == 'rotate':
                f = [x,y,c*u-s*v,s*u+c*v]
            elif kind == 'harmonic':
                f = [x,y,c*u,c*v,s*u,s*v]
            else:
                f = [x,y,u,v,c,s]
        return f+[1.0] if bias else f
    def fit(spec):
        raw = [features(spec,i,states[i][0],states[i][1],actions[i][0],actions[i][1]) for i in range(n)]
        p = len(raw[0])
        scales = [max(1e-9,math.sqrt(sum(f[j]*f[j] for f in raw)/n)) for j in range(p)]
        fs = [[f[j]/scales[j] for j in range(p)] for f in raw]
        gram = [[sum(f[j]*f[k] for f in fs)+(1e-12 if j == k else 0.0) for k in range(p)] for j in range(p)]
        z = [gram[j]+[1.0 if j == k else 0.0 for k in range(p)]+[sum(fs[i][j]*states[i+1][d] for i in range(n)) for d in range(2)] for j in range(p)]
        for k in range(p):
            pivot = max(range(k,p),key=lambda i:abs(z[i][k]))
            if abs(z[pivot][k]) < 1e-15:
                return None
            z[k],z[pivot] = z[pivot],z[k]
            div = z[k][k]
            z[k] = [v/div for v in z[k]]
            for i in range(p):
                if i != k:
                    div = z[i][k]
                    z[i] = [z[i][j]-div*z[k][j] for j in range(2*p+2)]
        co = [[z[j][2*p+d]/scales[j] for j in range(p)] for d in range(2)]
        residuals = [[states[i+1][d]-sum(co[d][j]*raw[i][j] for j in range(p)) for d in range(2)] for i in range(n)]
        hats = [sum(f[j]*z[j][p+k]*f[k] for j in range(p) for k in range(p)) for f in fs]
        cv = math.sqrt(sum((residuals[i][d]/max(1e-5,1.0-hats[i]))**2 for i in range(n) for d in range(2))/(2*n))
        rmse = math.sqrt(sum(v*v for r in residuals for v in r)/(2*n))
        return {'spec':list(spec),'coefficients':co,'rmse':rmse,'loo_rmse':cv,'score':cv*(1.0+0.04*(p-4))}
    reports = []
    groups = {}
    def add(spec):
        r = fit(spec)
        if r is not None:
            reports.append(r)
            key = (spec[0],spec[1],spec[3])
            if key not in groups or r['rmse'] < groups[key]['rmse']:
                groups[key] = r
        return r
    for bias in [False,True]:
        add(('linear','t',0.0,bias))
        for w in [0.1,0.5,1.0,2.0,5.0,10.0,20.0,50.0]:
            add(('gain','t',w,bias))
    grids = [('t',0.02,40),('x',0.1,60),('r2',0.05,60),('t2',0.004,30),('y',0.4,50)]
    for axis,inc,count in grids:
        for j in range(-count,count+1):
            if j != 0:
                for bias in [False,True]:
                    add(('rotate',axis,j*inc,bias))
    for axis,inc,count in [('t',0.05,20),('x',0.2,35),('r2',0.1,35)]:
        for j in range(1,count+1):
            for bias in [False,True]:
                add(('harmonic',axis,j*inc,bias))
    for j in range(16,65):
        for bias in [False,True]:
            add(('forcing','t',0.025*j,bias))
    for j in range(1,31):
        for bias in [False,True]:
            add(('forcing','x',0.25*j,bias))
    initial_groups = list(groups.items())
    widths = {'t':0.05,'x':0.25,'r2':0.1,'t2':0.004,'y':0.4}
    for key,r in initial_groups:
        kind,axis,bias = key
        if kind not in ['rotate','harmonic','forcing']:
            continue
        center = r['spec'][2]
        width = widths[axis]
        left,right = center-width,center+width
        ratio = 0.6180339887498949
        x1,x2 = right-ratio*(right-left),left+ratio*(right-left)
        r1,r2 = fit((kind,axis,x1,bias)),fit((kind,axis,x2,bias))
        for rep in range(27):
            if r1 is None or r2 is None:
                break
            if r1['rmse'] < r2['rmse']:
                right,x2,r2 = x2,x1,r1
                x1 = right-ratio*(right-left)
                r1 = fit((kind,axis,x1,bias))
            else:
                left,x1,r1 = x1,x2,r2
                x2 = left+ratio*(right-left)
                r2 = fit((kind,axis,x2,bias))
        if r1 is not None:
            reports.append(r1)
        if r2 is not None:
            reports.append(r2)
    ranked = sorted(reports,key=lambda r:r['score'])
    distinct = []
    seen = set()
    for r in ranked:
        key = (r['spec'][0],r['spec'][1])
        if key not in seen:
            seen.add(key)
            distinct.append(r)
    def matrix(r,t,x,y):
        kind,axis,w,bias = r['spec']
        co = r['coefficients']
        dx = co[0][0]*x+co[0][1]*y+(co[0][-1] if bias else 0.0)
        dy = co[1][0]*x+co[1][1]*y+(co[1][-1] if bias else 0.0)
        b00,b01,b10,b11 = co[0][2],co[0][3],co[1][2],co[1][3]
        if kind == 'gain':
            g = 1.0/(1.0+w*0.36)
            b00,b01,b10,b11 = b00*g,b01*g,b10*g,b11*g
        elif kind != 'linear':
            angle = w*phase(axis,t,x,y)
            c,s = math.cos(angle),math.sin(angle)
            if kind == 'rotate':
                b00,b01,b10,b11 = b00*c+b01*s,-b00*s+b01*c,b10*c+b11*s,-b10*s+b11*c
            elif kind == 'harmonic':
                b00,b01,b10,b11 = co[0][2]*c+co[0][4]*s,co[0][3]*c+co[0][5]*s,co[1][2]*c+co[1][4]*s,co[1][3]*c+co[1][5]*s
            else:
                dx += co[0][4]*c+co[0][5]*s
                dy += co[1][4]*c+co[1][5]*s
        return dx,dy,b00,b01,b10,b11
    def summarize(r):
        result = dict(r)
        dx,dy,a,b,c,d = matrix(r,n,states[-1][0],states[-1][1])
        result['next_predictions'] = [[dx+a*u+b*v,dy+c*u+d*v] for u,v in menu]
        return result
    chosen = [r for r in distinct if max(abs(v) for c in r['coefficients'] for v in c) < 50.0][:5]
    plans = []
    for r in chosen:
        co = r['coefficients']
        a,b,c,d = co[0][0],co[0][1],co[1][0],co[1][1]
        h11,h12,h22 = 0.0,0.0,0.0
        for t in range(n,28):
            nominal_x = states[-1][0]*(28-t)/(28-n)
            zz,ww,b00,b01,b10,b11 = matrix(r,t,nominal_x,0.0)
            h11 += (b00*b00+b01*b01)/(28-n)
            h12 += (b00*b10+b01*b11)/(28-n)
            h22 += (b10*b10+b11*b11)/(28-n)
        p,q,s = 1.0,0.0,1.0
        for rep in range(24):
            det = max(1e-18,p*s-q*q)
            e,f,g = s/det+h11/0.05,-q/det+h12/0.05,p/det+h22/0.05
            det2 = max(1e-18,e*g-f*f)
            e,f,g = g/det2,-f/det2,e/det2
            p,q,s = 1.0+e*a*a+2*f*a*c+g*c*c,e*a*b+f*(a*d+b*c)+g*c*d,1.0+e*b*b+2*f*b*d+g*d*d
        scale = max(1e-12,(p+s)/2.0)
        p,q,s = p/scale,q/scale,s/scale
        candidate_reports = []
        for first in range(len(menu)):
