            escaped_at = None
            best_rejected_norm = None
            for t in range(n,32):
                rows = []
                ids = [first] if t == n else list(range(len(menu)))
                smallest = 1e100
                for oldscore,cost,x,y,mx,path,targets in beam:
                    dx,dy,b00,b01,b10,b11 = matrix(r,t,x,y)
