                        radius2 = xx*xx+yy*yy
                        smallest = min(smallest,radius2)
                        if radius2 > 16.0+1e-10:
                            continue
                        radius = math.sqrt(radius2)
                        value = p*xx*xx+2*q*xx*yy+s*yy*yy
                        if t+1 >= 28:
                            cc = cost+10000.0*max(0.0,radius-0.05)**2+radius2
