{"code":"import math

def act(history):
    xs = history['states']
    us = history['actions']
    menu = [[0.6,0.0],[0.519615242271,0.3],[0.3,0.519615242271],[0.0,0.6],[-0.3,0.519615242271],[-0.519615242271,0.3],[-0.6,0.0],[-0.519615242271,-0.3],[-0.3,-0.519615242271],[0.0,-0.6],[0.3,-0.519615242271],[0.519615242271,-0.3],[0.0,0.0]]
    def fit(rows, ys):
        n = len(rows)
        p = len(rows[0])
        if p >= n:
            return None
        g = [[sum(r[i]*r[j] for r in rows) for j in range(p)] for i in range(p)]
        rhs = [[sum(rows[t][i]*ys[t][k] for t in range(n)) for k in range(2)] for i in range(p)]
        a = [g[i] + rhs[i] + [float(i == j) for j in range(p)] for i in range(p)]
        for j in range(p):
            q = max(range(j,p), key=lambda i: abs(a[i][j]))
            if abs(a[q][j]) < 1e-12:
                return None
            a[j],a[q] = a[q],a[j]
            v = a[j][j]
            a[j] = [z/v for z in a[j]]
            for i in range(p):
                if i != j:
                    v = a[i][j]
                    a[i] = [a[i][k]-v*a[j][k] for k in range(2*p+2)]
        co = [[a[j][p+k] for j in range(p)] for k in range(2)]
        residuals = [[ys[t][k]-sum(rows[t][j]*co[k][j] for j in range(p)) for k in range(2)] for t in range(n)]
        hs = [sum(r[i]*a[i][p+2+j]*r[j] for i in range(p) for j in range(p)) for r in rows]
        rmse = math.sqrt(sum(v*v for e in residuals for v in e)/n)
        loo = math.sqrt(sum(sum(v*v for v in residuals[t])/max(1e-8,1-hs[t])**2 for t in range(n))/n)
        return {'rmse':rmse,'loo':loo,'coefficients':co}
    def feat(kind,k,x,u,t):
        a,b = x
        c,d = u
        r = math.sqrt(a*a+b*b)
        base = [a,b,c,d]
        if kind == 'linear':
            return base
        if kind == 'affine':
            return base+[1.0]
        if kind == 'radial':
            return base+[r**k*a,r**k*b]
        if kind == 'radial_affine':
            return base+[r**k*a,r**k*b,1.0]
        if kind == 'input_radial':
            return base+[r**k*c,r**k*d]
        if kind == 'input_radial_affine':
            return base+[r**k*c,r**k*d,1.0]
        if kind == 'radial_both':
            return base+[r**k*a,r**k*b,r**k*c,r**k*d]
        if kind == 'poly_x':
            return base+[a**j for j in range(2,int(k)+1)]+[1.0]
        if kind == 'quadratic_cross':
            return base+[1.0,a*a,a*b,b*b]
        if kind == 'tanh':
            return base+[math.tanh(k*a),math.tanh(k*b)]
        if kind == 'sine':
            return base+[math.sin(k*a),math.sin(k*b)]
        if kind == 'time_force':
            return base+[math.sin(k*t),math.cos(k*t)]
        if kind == 'time_force_affine':
            return base+[math.sin(k*t),math.cos(k*t),1.0]
        if kind == 'time_gain':
            return base+[t*c,t*d]
        if kind == 'time_drift':
            return base+[t*a,t*b]
        if kind == 'state_input_cross':
            return base+[a*c,a*d,b*c,b*d]
        if kind == 'input_polynomial':
            return base+[c*c,c*d,d*d,1.0]
        if kind == 'sin_input':
            return [a,b,math.sin(k*c),math.sin(k*d)]
        if kind == 'tanh_input':
            return [a,b,math.tanh(k*c),math.tanh(k*d)]
        arg = t if 'time' in kind else (r*r if 'radius2' in kind else (r if 'radius' in kind else a))
        ca,sa = math.cos(k*arg),math.sin(k*arg)
        if 'rotate_input' in kind:
            return [a,b,ca*c-sa*d,sa*c+ca*d]+([r*r*a,r*r*b] if 'cubic' in kind else [])
        if 'rotate_state' in kind:
            return [ca*a-sa*b,sa*a+ca*b,c,d]+([a,b] if 'plus' in kind else [])
        return base
    specs = [('linear',0.0),('affine',0.0),('quadratic_cross',0.0),('time_gain',0.0),('time_drift',0.0),('state_input_cross',0.0),('input_polynomial',0.0)]
    for kind in ['radial','radial_affine','input_radial','input_radial_affine','radial_both']:
        for k in [-2.0,-1.0,0.5,1.0,1.5,2.0,3.0,4.0]:
            specs.append((kind,k))
    for k in [2,3,4,5]:
        specs.append(('poly_x',k))
    for kind in ['tanh','sine','sin_input','tanh_input']:
        for k in [0.2,0.5,1.0,1.5,2.0,3.0,4.0]:
            specs.append((kind,k))
    scan_kinds = ['rotate_input_time','rotate_input_radius','rotate_input_radius2','rotate_input_time_cubic','rotate_input_radius_cubic','rotate_state_radius','rotate_state_radius2','rotate_state_radius_plus','rotate_state_radius2_plus','time_force','time_force_affine']
    for kind in scan_kinds:
        for j in range(-60,61):
            if j != 0:
                specs.append((kind,j*0.05))
    results = []
    for kind,k in specs:
        rows = [feat(kind,k,x,u,t) for t,(x,u) in enumerate(zip(xs[:-1],us))]
        res = fit(rows,xs[1:])
        if res is not None:
            res['kind'] = kind
            res['k'] = k
            results.append(res)
    best_by_kind = []
    for kind in sorted(set(r['kind'] for r in results)):
        vals = [r for r in results if r['kind'] == kind]
        best_by_kind.append(min(vals,key=lambda r:r['rmse']))
    refine = []
    for res in best_by_kind:
        if res['kind'] in scan_kinds:
            for j in range(-10,11):
                k = res['k']+j*0.005
                rows = [feat(res['kind'],k,x,u,t) for t,(x,u) in enumerate(zip(xs[:-1],us))]
                v = fit(rows,xs[1:])
                if v is not None:
                    v['kind'],v['k'] = res['kind'],k
                    refine.append(v)
    results += refine
    selected = sorted(results,key=lambda r:r['rmse'])[:8]+sorted(results,key=lambda r:r['loo'])[:8]
    selected += sorted(best_by_kind,key=lambda r:r['rmse'])[:12]
    seen = set()
    out = []
    for res in selected:
        key = (res['kind'],res['k'])
        if key in seen:
            continue
        seen.add(key)
        predictions = []
        for u in menu:
            f = feat(res['kind'],res['k'],xs[-1],u,len(us))
            predictions.append([sum(a*b for a,b in zip(f,c)) for c in res['coefficients']])
        norms = [math.sqrt(sum(z*z for z in y)) for y in predictions]
        item = dict(res)
        item['next_states'] = predictions
        item['next_norms'] = norms
        item['minimum_norm_action'] = min(range(len(menu)),key=lambda j:norms[j])
        out.append(item)
    return {'models':out,'best_by_family':[{'kind':r['kind'],'k':r['k'],'rmse':r['rmse'],'loo':r['loo']} for r in sorted(best_by_kind,key=lambda r:r['rmse'])]}
