            m[j] = [v0 / v for v0 in m[j]]
            for i in range(n):
                if i != j:
                    v = m[i][j]
                    m[i] = [m[i][k] - v * m[j][k] for k in range(n + 1)]
        return [m[i][-1] for i in range(n)]
